import 'dart:convert';import 'dart:io';
import 'package:flutter_test/flutter_test.dart';import 'package:gopeed/asan/legacy_history.dart';
void main(){test('legacy history handles .NET dates, Persian new year and unknown metrics',(){final row=LegacyRecord({'Path':'missing.zip','Finished':'2026-03-21T09:05:00','Size':1048576});expect(row.date,startsWith('1405/01/01'));expect(row.duration,'—');expect(row.average,'—');expect(row.size,'1.00 MB');expect(LegacyRecord({'Finished':'/Date(1774083900000)/'}).finished,isNotNull);});
test('old history is read without changing files or dropping deleted downloads',()async{final root=await Directory.systemTemp.createTemp('asan-history-test-');try{final file=File('${root.path}/session.json'),data=jsonEncode({'History':[{'Id':'known','Path':'removed.zip','Finished':'2026-03-21T09:05:00'}]});await file.writeAsString(data);final rows=await readLegacyHistory(root.path);expect(rows.length,1);expect(rows.single.name,'removed.zip');expect(await file.readAsString(),data);}finally{await root.delete(recursive:true);}});}
